    fn straight_line_program() -> OxProgram {
        let n = LocalId(0);
        let t0 = TempId(0);
        let long = NumericMode::Checked(NumericCoerceTarget::Long);
        let entry = OxBlock {
            id: BlockId(0),
            instrs: vec![
                OxInst::Assign {
                    dst: OxPlace::Local(n),
                    value: OxOperand::Const(OxConst::I32(10)),
                },
                OxInst::Arith {
                    dst: OxPlace::Temp(t0),
                    op: ArithOp::Add,
                    lhs: OxOperand::Use(OxPlace::Local(n)),
                    rhs: OxOperand::Const(OxConst::I32(5)),
                    mode: long,
                },
                OxInst::Arith {
                    dst: OxPlace::Local(n),
                    op: ArithOp::Mul,
                    lhs: OxOperand::Use(OxPlace::Temp(t0)),
                    rhs: OxOperand::Const(OxConst::I32(2)),
                    mode: long,
                },
            ],
            fault_target: Some(BlockId(1)),
            terminator: OxTerminator::Return,
        };
        let fault = OxBlock {
            id: BlockId(1),
            instrs: Vec::new(),
            fault_target: None,
            terminator: OxTerminator::FaultDispatch {
                resume: BlockId(0),
                resume_next: BlockId(2),
            },
        };
        let exit = OxBlock {
            id: BlockId(2),
            instrs: Vec::new(),
            fault_target: None,
            terminator: OxTerminator::Return,
        };
        let main = OxFunc {
            name: "Main".to_string(),
            kind: ProcedureKind::Sub,
            locals: vec![OxLocal {
                name: "n".to_string(),
                ty: OxTy::Long,
                array_element: None,
                param: None,
                escaped: false,
            }],
            temps: vec![OxTy::Long],
            param_count: 0,
            return_local: None,
            blocks: vec![entry, fault, exit],
            entry: BlockId(0),
        };
        OxProgram {
            funcs: vec![main],
            globals: vec![OxGlobal {
                name: "g".to_string(),
                ty: OxTy::Long,
                array_element: None,
            }],
            entry: Some(FuncId(0)),
            unit_name: "VBAProject".to_string(),
            ..OxProgram::empty()
        }
    }

